import fs from 'fs/promises';
import path from 'path';
import {
  Document,
  Packer,
  Paragraph,
  TextRun,
} from 'docx';

/**
 * Generates a Word document from an existing cover-letter string.
 * No AI calls are made here.
 *
 * @param companyName - Name of the company the letter is for.
 * @param coverLetter - Cover-letter text generated by the evaluator.
 * @returns Absolute path to the generated .docx file.
 */
export async function generateCoverLetterDocument(
  companyName: string,
  coverLetter: string,
): Promise<string> {
  // Create a filesystem-safe version of the company name.
  const safeCompanyName = companyName
    .replace(/[<>:"/\\|?*\x00-\x1F]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

  if (!safeCompanyName) {
    throw new Error('Cannot generate cover letter: invalid company name.');
  }

  if (!coverLetter.trim()) {
    throw new Error(
      `Cannot generate cover letter for ${companyName}: cover letter is empty.`,
    );
  }

  // Save cover letters alongside the other AI resources.
  const outputDirectory = path.join(__dirname, 'cover-letters');

  // Ensure the output directory exists.
  await fs.mkdir(outputDirectory, { recursive: true });

  // Construct the output filename.
  const fileName = `GAARDER-${safeCompanyName}-COVER.docx`;
  const filePath = path.join(outputDirectory, fileName);

  // Preserve line breaks without adding excessive space between paragraphs.
    const paragraphs = coverLetter
    .trim()
    .split(/\r?\n/)
    .map(
        (text) =>
        new Paragraph({
            children: [
            new TextRun({
                text,
                font: 'Arial',
            }),
            ],
            spacing: {
            after: 0,
            line: 276, // Approximately 1.15 line spacing.
            },
        }),
    );

    // Create the Word document.
    const document = new Document({
    styles: {
        default: {
        document: {
            run: {
            font: 'Arial',
            size: 20, // 11pt
            },
            paragraph: {
            spacing: {
                after: 0,
                line: 276,
            },
            },
        },
        },
    },
    sections: [
        {
        properties: {},
        children: paragraphs,
        },
    ],
    });

  // Convert the document to a .docx buffer.
  const buffer = await Packer.toBuffer(document);

  // Write the document to disk.
  await fs.writeFile(filePath, buffer);

  console.log(`[documents] Cover letter saved: ${filePath}`);

  return filePath;
}